-- The one Client note (ADR-0049). drizzle-kit emits the audit value, the table,
-- ENABLE RLS, the checks, the composite foreign key, the one-row index, and
-- the audit check. FORCE RLS and the grants are hand-written. app.clients
-- is not altered. There is no DELETE grant: an empty save clears the text.
ALTER TYPE "app"."audit_action" ADD VALUE 'client_note.saved';--> statement-breakpoint
CREATE TABLE "app"."client_notes" (
	"tenant_id" uuid DEFAULT app.current_tenant_id() NOT NULL,
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"client_id" uuid NOT NULL,
	"note" text,
	"version" integer DEFAULT 0 NOT NULL,
	"data_changed_at" timestamp with time zone,
	"data_changed_by" text,
	CONSTRAINT "client_notes_note" CHECK ("app"."client_notes"."note" is null or ("app"."client_notes"."note" = btrim("app"."client_notes"."note") and length("app"."client_notes"."note") between 1 and 2000)),
	CONSTRAINT "client_notes_version" CHECK ("app"."client_notes"."version" >= 0),
	CONSTRAINT "client_notes_data_change" CHECK (("app"."client_notes"."version" = 0 and "app"."client_notes"."data_changed_at" is null and "app"."client_notes"."data_changed_by" is null) or ("app"."client_notes"."version" >= 1 and "app"."client_notes"."data_changed_at" is not null and "app"."client_notes"."data_changed_by" <> ''))
);
--> statement-breakpoint
ALTER TABLE "app"."client_notes" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "app"."audit_entry" DROP CONSTRAINT "audit_entry_shape";--> statement-breakpoint
ALTER TABLE "app"."client_notes" ADD CONSTRAINT "client_notes_client_fk" FOREIGN KEY ("tenant_id","client_id") REFERENCES "app"."clients"("tenant_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "client_notes_one_per_client" ON "app"."client_notes" USING btree ("tenant_id","client_id");--> statement-breakpoint
